fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn archive(root:&Path,dir:&Path,dest:&Path,index:&mut BTreeMap<String,String>){
    for entry in fs::read_dir(dir).unwrap(){let e=entry.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();
        if e.file_type().unwrap().is_dir(){if ["target","source"].contains(&name.as_str()){continue;}archive(root,&p,dest,index);}
        else if ["rs","md","json","log","txt","proof","public"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or(""))&&! ["archive.log","archive-verification.log"].contains(&name.as_str()){
            let rel=p.strip_prefix(root).unwrap();let out=dest.join(rel);fs::create_dir_all(out.parent().unwrap()).unwrap();fs::copy(&p,&out).unwrap();index.insert(format!("artifacts/{}",rel.display()),hash(out));
        }
    }
}
